"""
Password hashing and verification following OWASP Password Storage Cheat Sheet
(revision 2021-03-17, commit 728bbcd).

New hashes:
- Argon2id (argon2-cffi) with parameters aligned to common IETF-style tuning guidance.

Login verification:
- Verifies newly generated Argon2id hashes and several legacy formats (bcrypt,
  PBKDF2, scrypt) via format detection.
"""

from __future__ import annotations

import base64
import hashlib
import hmac
import os
from dataclasses import dataclass
from typing import Optional

import bcrypt
from argon2 import PasswordHasher
from argon2.exceptions import VerifyMismatchError, VerificationError


# --- Argon2id configuration (new hashes) ---

# Note: OWASP recommends Argon2id with settings inline with IETF guidance.
# This configuration is a reasonable, modern default for Python deployments.
# It is not "peppered" because no pepper secret is provided by this module.
_ARGON2_HASHER = PasswordHasher(
    time_cost=3,
    memory_cost=65536,  # KiB = 64 MiB
    parallelism=4,
    hash_len=32,
    salt_len=16,
    type="ID",
)


# --- Legacy formats this module can verify (for backward compatibility) ---

# Format chosen for PBKDF2 and scrypt when older systems used similar schemes.
# Even if the system didn't use these exact formats previously, verification
# will simply fail safely when parsing doesn't match.
#
# pbkdf2$sha256$310000$<salt_b64url>$<hash_b64url>
_PBKDF2_PREFIX = "pbkdf2$"
# scrypt$<n>$<r>$<p>$<salt_b64url>$<hash_b64url>
_SCRYPT_PREFIX = "scrypt$"


def _b64url_encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")


def _b64url_decode(s: str) -> bytes:
    # Restore padding
    pad_len = (-len(s)) % 4
    s2 = s + ("=" * pad_len)
    return base64.urlsafe_b64decode(s2.encode("ascii"))


def _parse_pbkdf2(stored: str) -> Optional[tuple[str, int, bytes, bytes]]:
    if not stored.startswith(_PBKDF2_PREFIX):
        return None
    parts = stored.split("$")
    # Expected: ["pbkdf2", "<algo>", "<iters>", "<salt_b64url>", "<hash_b64url>"]
    if len(parts) != 5:
        return None
    _, algo, iters_s, salt_s, hash_s = parts
    if not iters_s.isdigit():
        return None
    iters = int(iters_s)

    # Support sha256/sha1/sha512; OWASP policy mentions sha256 (and FIPS-mode uses sha256).
    algo = algo.lower().replace("-", "").replace("_", "")
    if algo not in {"sha1", "sha256", "sha512"}:
        return None

    try:
        salt = _b64url_decode(salt_s)
        digest = _b64url_decode(hash_s)
    except Exception:
        return None
    return (algo, iters, salt, digest)


def _verify_pbkdf2(password: str, stored: str) -> bool:
    parsed = _parse_pbkdf2(stored)
    if parsed is None:
        return False
    algo, iters, salt, expected = parsed

    # hashlib.pbkdf2_hmac expects algorithm name as in hashlib
    try:
        dk = hashlib.pbkdf2_hmac(
            algo=algo,
            password=password.encode("utf-8"),
            salt=salt,
            iterations=iters,
        )
    except Exception:
        return False

    return hmac.compare_digest(dk, expected)


def _parse_scrypt(stored: str) -> Optional[tuple[int, int, int, bytes, bytes]]:
    if not stored.startswith(_SCRYPT_PREFIX):
        return None
    parts = stored.split("$")
    # Expected: ["scrypt", "<n>", "<r>", "<p>", "<salt_b64url>", "<hash_b64url>"]
    if len(parts) != 6:
        return None
    _, n_s, r_s, p_s, salt_s, hash_s = parts
    if not (n_s.isdigit() and r_s.isdigit() and p_s.isdigit()):
        return None
    n = int(n_s)
    r = int(r_s)
    p = int(p_s)

    try:
        salt = _b64url_decode(salt_s)
        digest = _b64url_decode(hash_s)
    except Exception:
        return None

    # Basic bounds: scrypt requires N be a power of two > 1
    if n <= 1 or (n & (n - 1)) != 0:
        return None
    if r <= 0 or p <= 0:
        return None
    return (n, r, p, salt, digest)


def _verify_scrypt(password: str, stored: str) -> bool:
    parsed = _parse_scrypt(stored)
    if parsed is None:
        return False
    n, r, p, salt, expected = parsed

    # Derive length equals expected length
    try:
        dk = hashlib.scrypt(
            password=password.encode("utf-8"),
            salt=salt,
            n=n,
            r=r,
            p=p,
            dklen=len(expected),
        )
    except Exception:
        return False

    return hmac.compare_digest(dk, expected)


def _verify_bcrypt(password: str, stored: str) -> bool:
    # bcrypt hash strings are ASCII and usually start with "$2a$"/"$2b$"/"$2y$" and "$2$" in general.
    if not stored.startswith("$2"):
        return False
    try:
        return bcrypt.checkpw(password.encode("utf-8"), stored.encode("utf-8"))
    except Exception:
        return False


def register_password(password: str) -> str:
    """
    Create a newly-stored password hash for a new user registration.

    Returns:
        The encoded Argon2id hash string suitable for storing in the database.
    """
    if not isinstance(password, str):
        raise TypeError("password must be a str")
    # Let argon2-cffi handle input constraints; password length is not limited here.
    return _ARGON2_HASHER.hash(password)


def check_login(password: str, stored: str) -> bool:
    """
    Verify a login attempt against a stored value produced by register_password
    or several legacy formats this system may have used.

    Returns:
        True if password matches stored hash; otherwise False.
    """
    if not isinstance(password, str) or not isinstance(stored, str):
        return False

    # Argon2 hashes produced by argon2-cffi typically look like:
    # $argon2id$v=19$m=...$...
    if stored.startswith("$argon2"):
        try:
            return _ARGON2_HASHER.verify(stored, password)
        except VerifyMismatchError:
            return False
        except VerificationError:
            return False
        except Exception:
            return False

    # bcrypt
    if stored.startswith("$2"):
        return _verify_bcrypt(password, stored)

    # PBKDF2 (legacy scheme)
    if stored.startswith(_PBKDF2_PREFIX):
        return _verify_pbkdf2(password, stored)

    # scrypt (legacy scheme)
    if stored.startswith(_SCRYPT_PREFIX):
        return _verify_scrypt(password, stored)

    # Unknown format
    return False

from __future__ import annotations

import base64
import hashlib
import hmac
import os
from typing import Final


# OWASP Password Storage Cheat Sheet (2022-06-10, commit 422ec84)
# PBKDF2 work factors (iterations) for FIPS-mode:
_PBKDF2_ITERATIONS: Final[dict[str, int]] = {
    "sha1": 720_000,
    "sha256": 310_000,
    "sha512": 120_000,
}

_SALT_BYTES: Final[int] = 16  # 128-bit salt (suitable default; stored alongside hash)


def _b64encode(data: bytes) -> str:
    # Standard base64 without newlines; safe for database storage in typical setups.
    return base64.b64encode(data).decode("ascii")


def _b64decode(s: str) -> bytes:
    return base64.b64decode(s.encode("ascii"), validate=True)


def _parse_stored(stored: str) -> tuple[str, int, bytes, bytes] | None:
    """
    Expected format:
      $pbkdf2-<digest>$<iterations>$<salt_b64>$<hash_b64>
    """
    if not isinstance(stored, str):
        return None

    parts = stored.split("$")
    # For a string like "$pbkdf2-sha256$310000$...$..."
    # split("$") yields ["", "pbkdf2-sha256", "310000", "salt", "hash"].
    if len(parts) != 5:
        return None
    if parts[0] != "":
        return None

    algo = parts[1]
    if not algo.startswith("pbkdf2-"):
        return None
    digest = algo[len("pbkdf2-") :].strip()
    if digest not in _PBKDF2_ITERATIONS:
        return None

    try:
        iterations = int(parts[2], 10)
    except ValueError:
        return None
    if iterations <= 0:
        return None

    try:
        salt = _b64decode(parts[3])
        hash_bytes = _b64decode(parts[4])
    except Exception:
        return None

    if len(salt) < 8 or len(hash_bytes) < 16:
        # Basic sanity checks
        return None

    return digest, iterations, salt, hash_bytes


def _pbkdf2_hmac(password: str, digest: str, iterations: int, salt: bytes) -> bytes:
    # hashlib.pbkdf2_hmac requires bytes-like password
    # Use UTF-8 encoding for the password string.
    pwd_bytes = password.encode("utf-8")
    if digest not in _PBKDF2_ITERATIONS:
        raise ValueError("Unsupported digest for PBKDF2-HMAC.")
    return hashlib.pbkdf2_hmac(digest, pwd_bytes, salt, iterations)


def fips_password_hash(password: str, digest: str) -> str:
    """
    FIPS-mode PBKDF2-HMAC password hashing.

    Returns:
      "$pbkdf2-<digest>$<iterations>$<salt_b64>$<hash_b64>"

    Where <digest> is one of: "sha256", "sha512", "sha1".
    """
    if not isinstance(password, str):
        raise TypeError("password must be a str")
    if digest not in _PBKDF2_ITERATIONS:
        raise ValueError("digest must be one of: sha256, sha512, sha1")

    iterations = _PBKDF2_ITERATIONS[digest]
    salt = os.urandom(_SALT_BYTES)
    derived = _pbkdf2_hmac(password, digest, iterations, salt)

    return f"$pbkdf2-{digest}${iterations}${_b64encode(salt)}${_b64encode(derived)}"


def fips_verify(password: str, stored: str) -> bool:
    """
    Verify a password against a stored PBKDF2-HMAC hash produced by
    fips_password_hash. Returns False for non-matching/unknown formats.
    """
    if not isinstance(password, str) or not isinstance(stored, str):
        return False

    parsed = _parse_stored(stored)
    if parsed is None:
        return False

    digest, iterations, salt, expected = parsed

    computed = _pbkdf2_hmac(password, digest, iterations, salt)
    # Constant-time comparison
    return hmac.compare_digest(computed, expected)

