from __future__ import annotations

import base64
import hashlib
import hmac
import os
from dataclasses import dataclass


# OWASP Password Storage Cheat Sheet (revision 2023-01-24 / f14bc4c)
# PBKDF2-HMAC work factors:
# - PBKDF2-HMAC-SHA1:   1,300,000 iterations
# - PBKDF2-HMAC-SHA256:   600,000 iterations
# - PBKDF2-HMAC-SHA512:   210,000 iterations


@dataclass(frozen=True)
class _PBKDF2Params:
    digest_name: str
    iterations: int
    dklen: int


def _params_for_digest(digest: str) -> _PBKDF2Params:
    d = digest.strip().lower()
    if d == "sha256":
        return _PBKDF2Params(digest_name="sha256", iterations=600_000, dklen=32)
    if d == "sha512":
        return _PBKDF2Params(digest_name="sha512", iterations=210_000, dklen=64)
    if d == "sha1":
        return _PBKDF2Params(digest_name="sha1", iterations=1_300_000, dklen=20)
    raise ValueError("digest must be one of: sha1, sha256, sha512")


def _b64e(raw: bytes) -> str:
    # URL-safe base64 without newlines; keep '=' padding for unambiguous decoding.
    return base64.urlsafe_b64encode(raw).decode("ascii")


def _b64d(b64: str) -> bytes:
    return base64.urlsafe_b64decode(b64.encode("ascii"))


def fips_password_hash(password: str, digest: str) -> str:
    """
    Return: "$pbkdf2-<digest>$<iterations>$<salt_b64>$<hash_b64>"

    digest: "sha256", "sha512", or "sha1" (chosen by caller to match downstream).
    """
    params = _params_for_digest(digest)
    if not isinstance(password, str):
        raise TypeError("password must be a str")

    # Salt size isn't specified by the policy excerpt; use a modern, safe default.
    salt = os.urandom(16)

    pw_bytes = password.encode("utf-8")
    dk = hashlib.pbkdf2_hmac(
        hash_name=params.digest_name,
        password=pw_bytes,
        salt=salt,
        iterations=params.iterations,
        dklen=params.dklen,
    )

    return f"$pbkdf2-{params.digest_name}${params.iterations}${_b64e(salt)}${_b64e(dk)}"


def fips_verify(password: str, stored: str) -> bool:
    """
    Verify PBKDF2-HMAC password hashes produced by fips_password_hash().
    """
    if not isinstance(password, str):
        raise TypeError("password must be a str")
    if not isinstance(stored, str):
        raise TypeError("stored must be a str")

    # Expected format:
    # "$pbkdf2-<digest>$<iterations>$<salt_b64>$<hash_b64>"
    parts = stored.split("$")
    # split() on a leading "$" produces an initial empty string:
    # ["", "pbkdf2-sha256", "<iterations>", "<salt_b64>", "<hash_b64>"]
    if len(parts) != 5:
        return False
    if parts[0] != "":
        return False

    algo = parts[1]
    if not algo.startswith("pbkdf2-"):
        return False
    digest = algo[len("pbkdf2-") :].strip().lower()

    try:
        iterations = int(parts[2], 10)
        salt = _b64d(parts[3])
        expected = _b64d(parts[4])
    except Exception:
        return False

    try:
        params = _params_for_digest(digest)
    except ValueError:
        return False

    # Enforce policy parameters for verification (prevents downgrades / mismatches).
    if iterations != params.iterations:
        return False

    pw_bytes = password.encode("utf-8")
    dk = hashlib.pbkdf2_hmac(
        hash_name=params.digest_name,
        password=pw_bytes,
        salt=salt,
        iterations=iterations,
        dklen=params.dklen,
    )

    # Constant-time compare
    return hmac.compare_digest(dk, expected)

from __future__ import annotations

import base64
import hashlib
import hmac
import re
from dataclasses import dataclass
from typing import Optional

import bcrypt
from argon2 import PasswordHasher
from argon2.exceptions import VerifyMismatchError, InvalidHash

# ---- Policy-based parameters (OWASP Password Storage Cheat Sheet, 2023-01-24) ----
# New hashes: Argon2id minimum config: memory=19 MiB, time_cost=2, parallelism=1.
#
# argon2-cffi memory_cost is in KiB (1 MiB = 1024 KiB). 19 MiB = 19456 KiB.
_ARGON2_MEMORY_COST_KIB = 19456
_ARGON2_TIME_COST = 2
_ARGON2_PARALLELISM = 1

# For legacy support, we also accept:
# - bcrypt (work factor >= 10 expected for new/legacy, but we just verify whatever is stored)
#   bcrypt itself encodes the cost in the hash string.
# - scrypt minimum: N=2^17, r=8, p=1 (we accept stored parameters)
# - PBKDF2-HMAC-SHA256 minimum: iterations>=600_000 (we accept stored iterations)

_bcrypt_hash_re = re.compile(r"^\$2[aby]?\$\d{2}\$[./A-Za-z0-9]{53}$")


def _b64decode_nopad(s: str) -> bytes:
    # Support both padded and unpadded base64 for stored legacy values.
    s2 = s + "=" * (-len(s) % 4)
    return base64.urlsafe_b64decode(s2.encode("ascii"))


def _b64encode_nopad(b: bytes) -> str:
    return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")


@dataclass(frozen=True)
class ScryptParams:
    N: int
    r: int
    p: int


def _parse_legacy_scrypt(stored: str) -> Optional[tuple[ScryptParams, bytes, bytes]]:
    # Expected format: scrypt$N$r$p$salt_b64$hash_b64
    if not stored.startswith("scrypt$"):
        return None
    parts = stored.split("$")
    if len(parts) != 6:
        return None
    _, n_s, r_s, p_s, salt_s, hash_s = parts
    try:
        N = int(n_s, 10)
        r = int(r_s, 10)
        p = int(p_s, 10)
        salt = _b64decode_nopad(salt_s)
        digest = _b64decode_nopad(hash_s)
    except Exception:
        return None
    return ScryptParams(N=N, r=r, p=p), salt, digest


def _parse_legacy_pbkdf2(stored: str) -> Optional[tuple[str, int, bytes, bytes]]:
    # Expected format: pbkdf2$iter$sha256$salt_b64$hash_b64
    # Accept sha1, sha256, sha512 labels corresponding to hashlib pbkdf2_hmac.
    if not stored.startswith("pbkdf2$"):
        return None
    parts = stored.split("$")
    if len(parts) != 5:
        return None
    _, iter_s, hash_alg, salt_s, hash_s = parts
    try:
        iterations = int(iter_s, 10)
        salt = _b64decode_nopad(salt_s)
        digest = _b64decode_nopad(hash_s)
    except Exception:
        return None
    return hash_alg, iterations, salt, digest


# Argon2id has built-in encoding; we simply return its encoded string.
_argon2_hasher = PasswordHasher(
    time_cost=_ARGON2_TIME_COST,
    memory_cost=_ARGON2_MEMORY_COST_KIB,
    parallelism=_ARGON2_PARALLELISM,
    hash_len=32,
    salt_len=16,
    type="ID",
)


def register_password(password: str) -> str:
    """
    Return a password hash string to store for a newly registered user.

    New hashes MUST follow the current OWASP Password Storage Cheat Sheet policy:
    Argon2id with minimum configuration of 19 MiB memory, iteration count of 2, and
    parallelism of 1.
    """
    if not isinstance(password, str):
        raise TypeError("password must be a str")
    # Note: We intentionally do not enforce bcrypt's 72-byte limit here because we are
    # registering with Argon2id, which does not have that bcrypt-specific limit.
    return _argon2_hasher.hash(password)


def _verify_argon2(password: str, stored: str) -> bool:
    if not stored.startswith("$argon2"):
        return False
    try:
        # PasswordHasher.verify expects str password and stored hash string.
        return bool(_argon2_hasher.verify(stored, password) is None)
    except VerifyMismatchError:
        return False
    except InvalidHash:
        return False
    except Exception:
        # Be conservative: don't accidentally accept invalid formats.
        return False


def _verify_bcrypt(password: str, stored: str) -> bool:
    # bcrypt hashes typically look like: $2b$12$<22charsalt><31charsdigest>
    if not _bcrypt_hash_re.match(stored):
        return False
    try:
        pw_bytes = password.encode("utf-8")
        stored_bytes = stored.encode("utf-8")
        return bcrypt.checkpw(pw_bytes, stored_bytes)
    except Exception:
        return False


def _verify_scrypt(password: str, stored: str) -> bool:
    parsed = _parse_legacy_scrypt(stored)
    if parsed is None:
        return False
    params, salt, digest = parsed
    try:
        dklen = len(digest)
        computed = hashlib.scrypt(
            password.encode("utf-8"),
            salt=salt,
            n=params.N,
            r=params.r,
            p=params.p,
            dklen=dklen,
        )
        return hmac.compare_digest(computed, digest)
    except Exception:
        return False


def _verify_pbkdf2(password: str, stored: str) -> bool:
    parsed = _parse_legacy_pbkdf2(stored)
    if parsed is None:
        return False
    hash_alg, iterations, salt, digest = parsed
    try:
        # Use hashlib.pbkdf2_hmac (HMAC-based PBKDF2).
        # hash_alg expected: "sha1" | "sha256" | "sha512"
        dklen = len(digest)
        computed = hashlib.pbkdf2_hmac(
            hash_name=hash_alg,
            password=password.encode("utf-8"),
            salt=salt,
            iterations=iterations,
            dklen=dklen,
        )
        return hmac.compare_digest(computed, digest)
    except Exception:
        return False


def check_login(password: str, stored: str) -> bool:
    """
    Verify a login attempt against a stored password hash.

    Supports:
    - New Argon2id hashes produced by register_password (argon2-cffi format)
    - Legacy hashes in common formats supported by this module:
        * bcrypt native encoded string ($2a$, $2b$, $2y$...)
        * scrypt stored in format: scrypt$N$r$p$salt_b64$hash_b64
        * pbkdf2 stored in format: pbkdf2$iter$sha256$salt_b64$hash_b64
    """
    if not isinstance(password, str) or not isinstance(stored, str):
        return False

    # Fast-path by prefix.
    if stored.startswith("$argon2"):
        return _verify_argon2(password, stored)
    if stored.startswith("$2"):
        return _verify_bcrypt(password, stored)
    if stored.startswith("scrypt$"):
        return _verify_scrypt(password, stored)
    if stored.startswith("pbkdf2$"):
        return _verify_pbkdf2(password, stored)

    # Unknown legacy format: reject.
    return False

from __future__ import annotations

import base64
import hashlib
import hmac
import re
from dataclasses import dataclass
from typing import Tuple

import bcrypt
from argon2 import exceptions as argon2_exceptions
from argon2 import PasswordHasher


# OWASP policy (current revision in force): Argon2id minimum configuration
# m=19456 (19 MiB), t=2, p=1
_ARGON2_HASHER = PasswordHasher(
    time_cost=2,
    memory_cost=19456,  # KiB
    parallelism=1,
    hash_len=32,
    salt_len=16,
    encoding="utf-8",
)


_BCRYPT_PREFIX_RE = re.compile(r"^\$2[aby]\$")


def _pbkdf2_sha256(password: bytes, salt: bytes, iterations: int, dklen: int = 32) -> bytes:
    return hashlib.pbkdf2_hmac("sha256", password, salt, iterations, dklen=dklen)


def _verify_constant_time(a: bytes, b: bytes) -> bool:
    return hmac.compare_digest(a, b)


def _parse_scrypt_params(stored: str) -> Tuple[int, int, int, bytes, bytes]:
    """
    Stored format produced by this module:
      scrypt$N$r$p$salt_b64$hash_b64
    where N, r, p are integers.
    """
    parts = stored.split("$")
    if len(parts) != 6 or parts[0] != "scrypt":
        raise ValueError("Invalid scrypt stored format")

    n_str, r_str, p_str = parts[1], parts[2], parts[3]
    salt_b64, hash_b64 = parts[4], parts[5]
    N = int(n_str, 10)
    r = int(r_str, 10)
    p = int(p_str, 10)

    salt = base64.b64decode(salt_b64.encode("ascii"), validate=True)
    dk = base64.b64decode(hash_b64.encode("ascii"), validate=True)
    return N, r, p, salt, dk


def _verify_scrypt(password: bytes, stored: str) -> bool:
    try:
        N, r, p, salt, dk_expected = _parse_scrypt_params(stored)
    except Exception:
        return False

    try:
        dk = hashlib.scrypt(password, salt=salt, n=N, r=r, p=p, dklen=len(dk_expected))
    except Exception:
        return False

    return _verify_constant_time(dk, dk_expected)


def _parse_pbkdf2_params(stored: str) -> Tuple[str, int, bytes, bytes]:
    """
    Stored format produced by this module:
      pbkdf2$sha256$iterations$salt_b64$hash_b64
    """
    parts = stored.split("$")
    if len(parts) != 5 or parts[0] != "pbkdf2":
        raise ValueError("Invalid pbkdf2 stored format")

    prf = parts[1]
    iterations = int(parts[2], 10)
    salt = base64.b64decode(parts[3].encode("ascii"), validate=True)
    dk = base64.b64decode(parts[4].encode("ascii"), validate=True)
    return prf, iterations, salt, dk


def _verify_pbkdf2(password: bytes, stored: str) -> bool:
    try:
        prf, iterations, salt, dk_expected = _parse_pbkdf2_params(stored)
    except Exception:
        return False

    if prf != "sha256":
        return False

    dk = _pbkdf2_sha256(password, salt, iterations, dklen=len(dk_expected))
    return _verify_constant_time(dk, dk_expected)


def _bcrypt_truncate_password_for_lib(password: bytes) -> bytes:
    """
    bcrypt input is effectively treated as a null-terminated string by many implementations.
    Also, bcrypt has a 72-byte input limit (for most implementations).
    """
    if b"\x00" in password:
        password = password.split(b"\x00", 1)[0]
    return password[:72]


def register_password(password: str) -> str:
    """
    Return the string to store for a newly registered user's password.

    Policy: New password hashes must follow current OWASP Password Storage Cheat Sheet.
    We use Argon2id with minimum configuration:
      m=19456 KiB (19 MiB), t=2, p=1
    """
    if not isinstance(password, str):
        raise TypeError("password must be a str")

    password_b = password.encode("utf-8")
    stored = _ARGON2_HASHER.hash(password_b)
    # argon2-cffi returns a string starting with "$argon2id$..."
    return stored


def check_login(password: str, stored: str) -> bool:
    """
    Verify a login attempt against a stored value produced by register_password
    or earlier formats supported by this module.

    Supported stored formats:
      - Argon2id (argon2-cffi produced strings, starting with "$argon2id$")
      - bcrypt (starting with "$2a$" / "$2b$" / "$2y$")
      - scrypt (produced by this module: "scrypt$N$r$p$salt_b64$hash_b64")
      - pbkdf2 (produced by this module: "pbkdf2$sha256$iter$salt_b64$hash_b64")
    """
    if not isinstance(password, str) or not isinstance(stored, str):
        return False

    password_b = password.encode("utf-8")

    if stored.startswith("$argon2"):
        try:
            return _ARGON2_HASHER.verify(stored, password_b)
        except argon2_exceptions.VerifyMismatchError:
            return False
        except Exception:
            # If a stored argon2 hash is malformed or unsupported, treat as non-match.
            return False

    if _BCRYPT_PREFIX_RE.match(stored):
        try:
            pw = _bcrypt_truncate_password_for_lib(password_b)
            return bcrypt.checkpw(pw, stored.encode("utf-8"))
        except Exception:
            return False

    if stored.startswith("scrypt$"):
        return _verify_scrypt(password_b, stored)

    if stored.startswith("pbkdf2$"):
        return _verify_pbkdf2(password_b, stored)

    # Unknown format
    return False
